from pathlib import Path
p=Path('/challenge/observations.npz'); z=np.load(p)
for k in z.files:
 a=z[k]; print(k,a.shape,a.dtype, 'range', (a.min(),a.max()) if a.size and a.dtype.kind in 'iuf' else '')
print('first values:')
for k in z.files:
 a=z[k]
 if a.size<100: print(k,a)
 elif a.ndim<=2: print(k,a[:3])

import numpy as np
z=np.load('/challenge/observations.npz');X=z['tokens'];P=z['probabilities'];Y=P.argmax(-1)
for t in range(24):
 q=P[:,t];print('pos',t,'pmax',round(q.max(-1).mean(),4),'std',round(q.max(-1).std(),4),'argmax freq',np.bincount(Y[:,t],minlength=16).tolist())
print('examples last3 -> top:')
for r in range(3):
 print([(X[r,t-3:t].tolist(),int(Y[r,t]),round(float(P[r,t].max()),3)) for t in range(3,14)])
# affine arithmetic and xor search
h=np.stack([X[:,2:23].ravel(),X[:,1:22].ravel(),X[:,0:21].ravel()],axis=1); y=Y[:,3:].ravel()
best=[]
for a in range(16):
 for b in range(16):
  for c in range(16):
   d=(y-h@np.array([a,b,c]))%16
   ct=np.bincount(d,minlength=16);n=int(ct.max())
   best.append((n,a,b,c,int(ct.argmax())))
print('best mod16',sorted(best,reverse=True)[:15])
best=[]
for a in range(16):
 for b in range(16):
  for c in range(16):
   d=y^((h[:,0]*a)%16)^((h[:,1]*b)%16)^((h[:,2]*c)%16)
   ct=np.bincount(d,minlength=16);best.append((int(ct.max()),a,b,c,int(ct.argmax())))
print('best mult xor',sorted(best,reverse=True)[:5]); print('N',len(y))
# pooled conditional consistency and heldout mean
for k in range(1,6):
 groups={}
 for r in range(128):
  for t in range(k,24):groups.setdefault(tuple(X[r,t-k:t]),[]).append((r,t))
 count=tot=agree=0; mse=[]
 for ids in groups.values():
  if len(ids)<2:continue
  vals=np.array([P[r,t] for r,t in ids]); labs=vals.argmax(-1); count+=1;tot+=len(ids);agree+=max(np.bincount(labs,minlength=16));mse.extend(((vals-vals.mean(0))**2).mean(-1))
 print('pooled',k,'repeated groups',count,'rows',tot,'top agree',agree/max(tot,1),'mse',np.mean(mse) if mse else None)

