 q=P[:,3:][X[:,:21]==a];print(a,'n',len(q),'top',q.argmax(-1)[:8], 'mean',np.round(q.mean(0),3), 'sdmax',round(q.max(-1).std(),4))
# check exact p top and observed next token likelihood
