from pathlib import Path
import json, ast, math
out=Path('/output/submission')
mechanism=out/'mechanism.md'
text=mechanism.read_text()
text+='\n## Corruption-law uncertainty\nThe exact uniform 0.70/0.02 transition law is only an idealization. The sampled transition-count diagnostic gives a parametric trajectory-bootstrap tail fraction of approximately 0.036 (2000 replicates). This modest discrepancy cautions against asserting exactly uniform corruption; nonuniform or source-dependent corruption remains plausible. The diagnostic was performed after discovering the mechanism, so it is descriptive rather than an independent confirmation. Correct-transition event autocorrelations at tested lags are small, but do not prove independent noise. None of these uncertainties changes the exact observed lag-three modal permutation.\n'
mechanism.write_text(text)
meta=json.loads((out/'submission.json').read_text())
meta['assumptions']+=' Exact uniform corruption is not asserted: a sampled-transition bootstrap mildly challenges that simplification; nonuniform or source-dependent corruption remains an alternative.'
(out/'submission.json').write_text(json.dumps(meta,indent=2))
assert set(meta)=={'schema_version','predictor','mechanism','hypothesis','assumptions','resources'}
for key in ['predictor','mechanism']:
    assert not Path(meta[key]).is_absolute()
    assert (out/meta[key]).is_file()
ast.parse((out/meta['predictor']).read_text())
params=json.loads((out/'parameters.json').read_text())
def check(x):
    if isinstance(x,dict):
        for v in x.values(): check(v)
    elif isinstance(x,list):
        for v in x: check(v)
    else: assert isinstance(x,(int,float)) and math.isfinite(x)
check(params)
print('Submission ready: noisy lag-three permutation, independently executable calibrated predictor, structural reference, evidence and uncertainty. Neural instances/executions: 0; additional teacher queries: 0.')
